const clientCode = `#!/usr/bin/env python3
# -*- coding: utf-8 -*-
"""
Sina Finance 7×24 News Feed Client
完整的新浪财经7×24快讯API客户端

依赖: pip install requests
"""

import json
import re
import time
import csv
import random
from dataclasses import dataclass, field
from enum import IntEnum
from typing import List, Optional, Generator, Dict, Any
import requests


# ─── 枚举：分类标签 ────────────────────────────────────────────────────────────
class TagID(IntEnum):
    ALL        = 0    # 全部
    MACRO      = 1    # 宏观
    INDUSTRY   = 2    # 行业
    COMPANY    = 3    # 公司
    MARKET     = 5    # 市场
    OTHER      = 8    # 其他
    FOCUS      = 9    # 焦点
    A_SHARE    = 10   # A股
    INTL       = 102  # 国际
    TWO_SESS   = 110  # 两会（时效性）
    ORIGINAL   = 202  # 原创


# ─── 数据模型 ──────────────────────────────────────────────────────────────────
@dataclass
class StockRef:
    market: str    # cn/us/hk/fund/global/commodity/worldIndex/foreign
    symbol: str    # 股票代码
    name: str      # 股票名称

    def __str__(self):
        return f"{self.name}({self.market}:{self.symbol})"


@dataclass
class FeedItem:
    id: int
    type: int           # 0=文本, 1=含图片
    rich_text: str
    create_time: str
    update_time: str
    is_delete: int
    tags: List[Dict]    = field(default_factory=list)
    stocks: List[StockRef] = field(default_factory=list)
    images: List[str]   = field(default_factory=list)
    doc_url: str        = ""
    like_nums: int      = 0
    comment_count: int  = 0

    @property
    def has_images(self) -> bool:
        return bool(self.images)

    @property
    def tag_names(self) -> List[str]:
        return [t.get("name", "") for t in self.tags]

    @property
    def stock_names(self) -> List[str]:
        return [s.name for s in self.stocks]

    def __str__(self):
        return f"[{self.create_time}] {self.rich_text[:80]}..."


@dataclass
class PageInfo:
    total_page: int
    page_size: int
    page: int
    total_num: int


@dataclass
class FeedResponse:
    items: List[FeedItem]
    max_id: int
    min_id: int
    page_info: PageInfo
    raw: Dict = field(default_factory=dict, repr=False)

    @property
    def has_more(self) -> bool:
        return self.page_info.page < self.page_info.total_page


# ─── 解析工具函数 ──────────────────────────────────────────────────────────────
def _parse_jsonp(text: str) -> Dict:
    """剥离JSONP包装，提取JSON数据"""
    m = re.search(r'\((\{.*\})\)', text, re.DOTALL)
    if not m:
        raise ValueError(f"无法解析JSONP响应: {text[:200]}")
    return json.loads(m.group(1))


def _parse_stocks(ext_str: str) -> List[StockRef]:
    """解析ext字段中的股票信息（需二次json.loads）"""
    if not ext_str:
        return []
    try:
        ext = json.loads(ext_str)
        stocks = ext.get("stocks") or []
        return [
            StockRef(
                market=s.get("market", ""),
                symbol=s.get("symbol", ""),
                name=s.get("key", "")
            )
            for s in stocks if isinstance(s, dict)
        ]
    except (json.JSONDecodeError, TypeError):
        return []


def _parse_docurl(ext_str: str) -> str:
    """从ext字段提取文章链接"""
    if not ext_str:
        return ""
    try:
        ext = json.loads(ext_str)
        return ext.get("docurl", "")
    except (json.JSONDecodeError, TypeError):
        return ""


def _parse_item(raw: Dict) -> FeedItem:
    """将API原始条目转换为FeedItem"""
    ext_str = raw.get("ext", "")
    multimedia = raw.get("multimedia") or {}
    img_urls = multimedia.get("img_url") or []
    comments = raw.get("comment_list") or {}

    return FeedItem(
        id           = int(raw.get("id", 0)),
        type         = int(raw.get("type", 0)),
        rich_text    = raw.get("rich_text", ""),
        create_time  = raw.get("create_time", ""),
        update_time  = raw.get("update_time", ""),
        is_delete    = int(raw.get("is_delete", 0)),
        tags         = raw.get("tag") or [],
        stocks       = _parse_stocks(ext_str),
        images       = img_urls if isinstance(img_urls, list) else [],
        doc_url      = _parse_docurl(ext_str),
        like_nums    = int(raw.get("like_nums", 0)),
        comment_count= int(comments.get("total", 0)),
    )


def _parse_response(data: Dict) -> FeedResponse:
    """解析完整API响应"""
    result = data.get("result", {})
    status = result.get("status", {})
    if status.get("code") != 0:
        raise ValueError(f"API返回错误: {status.get('msg')} (code={status.get('code')})")

    feed = result.get("data", {}).get("feed", {})
    raw_list = feed.get("list") or []

    # 过滤已删除条目
    items = [_parse_item(r) for r in raw_list if r.get("is_delete") == 0]

    pi = feed.get("page_info") or {}
    page_info = PageInfo(
        total_page = int(pi.get("totalPage", 1)),
        page_size  = int(pi.get("pageSize", 20)),
        page       = int(pi.get("page", 1)),
        total_num  = int(pi.get("totalNum", 0)),
    )

    return FeedResponse(
        items     = items,
        max_id    = int(feed.get("max_id", 0)),
        min_id    = int(feed.get("min_id", 0)),
        page_info = page_info,
        raw       = data,
    )


# ─── 主客户端 ──────────────────────────────────────────────────────────────────
class Sina7x24Client:
    """
    新浪财经7×24快讯客户端

    用法:
        client = Sina7x24Client()
        response = client.get_latest()
        for item in response.items:
            print(item)
    """

    BASE_URL  = "https://zhibo.sina.com.cn/api/zhibo/feed"
    ZHIBO_ID  = 152

    def __init__(self, delay: float = 1.0):
        """
        Args:
            delay: 请求间最小间隔秒数（建议≥1.0）
        """
        self.delay = delay
        self._last_req = 0.0
        self.session = requests.Session()
        self.session.headers.update({
            "User-Agent": (
                "Mozilla/5.0 (Windows NT 10.0; Win64; x64) "
                "AppleWebKit/537.36 (KHTML, like Gecko) "
                "Chrome/120.0.0.0 Safari/537.36"
            ),
            "Referer": "https://finance.sina.com.cn/",
            "Accept": "*/*",
        })

    def _throttle(self):
        """限速：确保请求间隔"""
        elapsed = time.time() - self._last_req
        if elapsed < self.delay:
            time.sleep(self.delay - elapsed + random.uniform(0, 0.3))
        self._last_req = time.time()

    def _request(self, params: Dict) -> FeedResponse:
        """执行HTTP请求并解析响应"""
        self._throttle()
        default_params = {
            "callback": "feedCallback",
            "zhibo_id": self.ZHIBO_ID,
            "dpc": 1,
            "type": 0,
            "_": int(time.time() * 1000),
        }
        default_params.update(params)

        resp = self.session.get(self.BASE_URL, params=default_params, timeout=10)
        resp.raise_for_status()
        data = _parse_jsonp(resp.text)
        return _parse_response(data)

    def get_latest(self, tag_id: TagID = TagID.ALL) -> FeedResponse:
        """获取最新快讯（第一页）"""
        return self._request({"page": 1, "page_size": 20, "tag_id": int(tag_id), "dire": "f", "id": 0})

    def get_page(self, tag_id: TagID = TagID.ALL, page: int = 1) -> FeedResponse:
        """获取指定页码"""
        return self._request({"page": page, "page_size": 20, "tag_id": int(tag_id), "dire": "f", "id": 0})

    def get_next_page(self, prev_response: FeedResponse, tag_id: TagID = TagID.ALL) -> FeedResponse:
        """获取前一响应的下一历史页"""
        return self._request({
            "page": prev_response.page_info.page + 1,
            "page_size": 20,
            "tag_id": int(tag_id),
            "dire": "b",
            "id": prev_response.min_id,
        })

    def get_updates(self, since_id: int, tag_id: TagID = TagID.ALL) -> FeedResponse:
        """获取比since_id更新的增量内容"""
        return self._request({"page": 1, "page_size": 20, "tag_id": int(tag_id), "dire": "f", "id": since_id})

    def iter_history(self, tag_id: TagID = TagID.ALL, max_pages: int = 10) -> Generator[FeedResponse, None, None]:
        """迭代历史数据，自动翻页"""
        resp = self.get_latest(tag_id)
        yield resp
        for _ in range(max_pages - 1):
            if not resp.has_more:
                break
            resp = self.get_next_page(resp, tag_id)
            yield resp

    def search(self, keyword: str, tag_id: TagID = TagID.ALL, max_pages: int = 5) -> List[FeedItem]:
        """在历史数据中搜索关键词"""
        results = []
        for resp in self.iter_history(tag_id, max_pages):
            for item in resp.items:
                if keyword in item.rich_text:
                    results.append(item)
        return results

    def get_stock_news(self, stock_name: str, max_pages: int = 5) -> List[FeedItem]:
        """获取包含指定股票的快讯"""
        results = []
        for resp in self.iter_history(TagID.ALL, max_pages):
            for item in resp.items:
                if any(stock_name in s.name or stock_name in s.symbol for s in item.stocks):
                    results.append(item)
        return results

    def get_all_categories(self) -> Dict[TagID, FeedResponse]:
        """获取所有分类的最新快讯"""
        return {tag: self.get_latest(tag) for tag in TagID}


# ─── 导出工具 ──────────────────────────────────────────────────────────────────
def export_json(items: List[FeedItem], filepath: str):
    data = []
    for item in items:
        data.append({
            "id": item.id, "create_time": item.create_time,
            "rich_text": item.rich_text, "tags": item.tag_names,
            "stocks": item.stock_names, "doc_url": item.doc_url,
            "images": item.images, "like_nums": item.like_nums,
        })
    with open(filepath, "w", encoding="utf-8") as f:
        json.dump(data, f, ensure_ascii=False, indent=2)
    print(f"✅ 已导出 {len(data)} 条 → {filepath}")


def export_csv(items: List[FeedItem], filepath: str):
    with open(filepath, "w", newline="", encoding="utf-8-sig") as f:  # utf-8-sig for Excel
        w = csv.writer(f)
        w.writerow(["ID", "时间", "内容", "标签", "股票", "文章链接", "点赞"])
        for item in items:
            w.writerow([
                item.id, item.create_time, item.rich_text,
                ";".join(item.tag_names), ";".join(item.stock_names),
                item.doc_url, item.like_nums,
            ])
    print(f"✅ 已导出 {len(items)} 条 → {filepath}")


def export_md(items: List[FeedItem], filepath: str):
    with open(filepath, "w", encoding="utf-8") as f:
        f.write("# 新浪财经7×24快讯\\n\\n")
        for item in items:
            f.write(f"## {item.create_time}\\n\\n")
            f.write(f"{item.rich_text}\\n\\n")
            if item.tag_names:
                f.write(f"**标签**: {', '.join(item.tag_names)}\\n\\n")
            if item.stocks:
                f.write(f"**相关股票**: {', '.join(item.stock_names)}\\n\\n")
            if item.doc_url:
                f.write(f"[查看全文]({item.doc_url})\\n\\n")
            f.write("---\\n\\n")
    print(f"✅ 已导出 {len(items)} 条 → {filepath}")


# ─── 示例运行 ──────────────────────────────────────────────────────────────────
if __name__ == "__main__":
    client = Sina7x24Client(delay=1.0)

    print("📡 获取最新快讯...")
    response = client.get_latest()
    print(f"共 {response.page_info.total_num} 条，本页 {len(response.items)} 条\\n")

    for item in response.items[:5]:
        print(f"[{item.create_time}] {item.rich_text[:60]}...")
        if item.stocks:
            print(f"  📈 相关股票: {', '.join(item.stock_names)}")

    # 搜索示例
    print("\\n🔍 搜索 '央行' ...")
    results = client.search("央行", max_pages=3)
    print(f"找到 {len(results)} 条相关快讯")
`;

const monitorCode = `#!/usr/bin/env python3
# -*- coding: utf-8 -*-
"""
Sina Finance 7×24 实时监控器
持续轮询新快讯，新内容触发回调
"""

import time
from typing import Callable, Set
from sina_7x24_client import Sina7x24Client, FeedItem, TagID


class FeedMonitor:
    """
    实时监控器，基于轮询检测新快讯

    用法:
        monitor = FeedMonitor()

        @monitor.on_new_item
        def handle(item):
            print(f"新快讯: {item}")

        monitor.start(interval=30)  # 每30秒检查一次
    """

    def __init__(self, tag_id: TagID = TagID.ALL, delay: float = 1.0):
        self.client = Sina7x24Client(delay=delay)
        self.tag_id = tag_id
        self._seen_ids: Set[int] = set()
        self._callbacks: list = []
        self._running = False
        self._max_id = 0

    def on_new_item(self, fn: Callable[[FeedItem], None]):
        """注册新快讯回调（支持装饰器用法）"""
        self._callbacks.append(fn)
        return fn

    def _initialize(self):
        """初始化：记录已存在条目，避免启动时触发历史通知"""
        print("🔄 初始化，加载现有条目ID...")
        resp = self.client.get_latest(self.tag_id)
        self._seen_ids = {item.id for item in resp.items}
        self._max_id = resp.max_id
        print(f"✅ 已记录 {len(self._seen_ids)} 个已有条目，max_id={self._max_id}")

    def _check(self):
        """检查一次增量更新"""
        resp = self.client.get_updates(self._max_id, self.tag_id)
        new_items = [item for item in resp.items if item.id not in self._seen_ids]

        if new_items:
            for item in sorted(new_items, key=lambda x: x.id):
                self._seen_ids.add(item.id)
                for cb in self._callbacks:
                    try:
                        cb(item)
                    except Exception as e:
                        print(f"⚠️ 回调异常: {e}")

            if resp.max_id > self._max_id:
                self._max_id = resp.max_id

        return len(new_items)

    def start(self, interval: int = 30):
        """
        开始监控（阻塞）

        Args:
            interval: 轮询间隔秒数
        """
        self._initialize()
        self._running = True
        print(f"🚀 开始监控，间隔 {interval} 秒...")

        while self._running:
            try:
                count = self._check()
                if count:
                    print(f"📬 发现 {count} 条新快讯")
                time.sleep(interval)
            except KeyboardInterrupt:
                print("\\n⏹ 监控已停止")
                break
            except Exception as e:
                print(f"❌ 请求异常: {e}，{interval} 秒后重试...")
                time.sleep(interval)

    def stop(self):
        self._running = False


# ─── 使用示例 ──────────────────────────────────────────────────────────────────
if __name__ == "__main__":
    monitor = FeedMonitor(tag_id=TagID.ALL)

    @monitor.on_new_item
    def on_news(item: FeedItem):
        print(f"\\n{'='*60}")
        print(f"🕐 {item.create_time}")
        print(f"📰 {item.rich_text}")
        if item.stocks:
            print(f"📈 股票: {', '.join(item.stock_names)}")
        if item.doc_url:
            print(f"🔗 {item.doc_url}")

    # 同时监控A股板块
    @monitor.on_new_item
    def filter_a_share(item: FeedItem):
        if "A股" in item.tag_names or "10" in str([t["id"] for t in item.tags]):
            # 可以在这里推送到微信/邮件/Telegram等
            pass

    monitor.start(interval=30)
`;

const asyncCode = `#!/usr/bin/env python3
# -*- coding: utf-8 -*-
"""
Sina Finance 7×24 异步客户端
使用 aiohttp 实现高并发请求

依赖: pip install aiohttp
"""

import asyncio
import json
import re
import time
from typing import Dict, List
import aiohttp

from sina_7x24_client import (
    TagID, FeedResponse, FeedItem,
    _parse_jsonp, _parse_response
)


class AsyncSina7x24Client:
    """
    异步版客户端，适合批量并发获取多分类数据

    用法:
        async with AsyncSina7x24Client() as client:
            resp = await client.get_latest()
            all_cats = await client.fetch_all_categories()
    """

    BASE_URL = "https://zhibo.sina.com.cn/api/zhibo/feed"
    ZHIBO_ID = 152

    def __init__(self, delay: float = 0.5):
        self.delay = delay
        self._session: aiohttp.ClientSession = None

    async def __aenter__(self):
        self._session = aiohttp.ClientSession(headers={
            "User-Agent": "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36",
            "Referer": "https://finance.sina.com.cn/",
        })
        return self

    async def __aexit__(self, *args):
        await self._session.close()

    async def _request(self, params: Dict) -> FeedResponse:
        default_params = {
            "callback": "feedCallback",
            "zhibo_id": self.ZHIBO_ID,
            "dpc": 1, "type": 0,
            "_": int(time.time() * 1000),
        }
        default_params.update(params)

        async with self._session.get(self.BASE_URL, params=default_params, timeout=aiohttp.ClientTimeout(total=10)) as resp:
            resp.raise_for_status()
            text = await resp.text()

        data = _parse_jsonp(text)
        return _parse_response(data)

    async def get_latest(self, tag_id: TagID = TagID.ALL) -> FeedResponse:
        """获取最新快讯"""
        return await self._request({"page": 1, "page_size": 20, "tag_id": int(tag_id), "dire": "f", "id": 0})

    async def get_updates(self, since_id: int, tag_id: TagID = TagID.ALL) -> FeedResponse:
        """增量更新"""
        return await self._request({"page": 1, "page_size": 20, "tag_id": int(tag_id), "dire": "f", "id": since_id})

    async def fetch_all_categories(self) -> Dict[TagID, FeedResponse]:
        """
        并发获取所有分类最新快讯
        注意：会并发发起多个请求，生产环境请控制并发数
        """
        tags = list(TagID)

        async def fetch_one(tag: TagID):
            await asyncio.sleep(self.delay * tags.index(tag) * 0.5)  # 错开请求
            return tag, await self.get_latest(tag)

        results = await asyncio.gather(*[fetch_one(t) for t in tags], return_exceptions=True)

        return {
            tag: resp
            for tag, resp in results
            if not isinstance(resp, Exception)
        }

    async def iter_pages(self, tag_id: TagID = TagID.ALL, max_pages: int = 5):
        """异步迭代多页数据"""
        resp = await self.get_latest(tag_id)
        yield resp

        for _ in range(max_pages - 1):
            if not resp.has_more:
                break
            await asyncio.sleep(self.delay)
            resp = await self._request({
                "page": resp.page_info.page + 1,
                "page_size": 20,
                "tag_id": int(tag_id),
                "dire": "b",
                "id": resp.min_id,
            })
            yield resp


# ─── 示例运行 ──────────────────────────────────────────────────────────────────
async def main():
    async with AsyncSina7x24Client() as client:
        print("📡 并发获取所有分类...")
        all_cats = await client.fetch_all_categories()

        for tag, resp in all_cats.items():
            print(f"[{tag.name}] {resp.page_info.total_num} 条，最新: {resp.items[0].create_time if resp.items else 'N/A'}")

if __name__ == "__main__":
    asyncio.run(main())
`;

const dbCode = `#!/usr/bin/env python3
# -*- coding: utf-8 -*-
"""
新浪财经7×24快讯 SQLite 持久化存储
"""

import json
import sqlite3
from contextlib import contextmanager
from typing import List, Optional
from sina_7x24_client import FeedItem


class FeedDatabase:
    """
    SQLite持久化存储

    用法:
        db = FeedDatabase("news.db")
        db.upsert(items)
        results = db.query(keyword="央行", limit=20)
    """

    CREATE_SQL = """
    CREATE TABLE IF NOT EXISTS items (
        id            INTEGER PRIMARY KEY,
        create_time   TEXT    NOT NULL,
        update_time   TEXT,
        rich_text     TEXT    NOT NULL,
        tags          TEXT,     -- JSON array
        stocks        TEXT,     -- JSON array
        images        TEXT,     -- JSON array
        doc_url       TEXT,
        like_nums     INTEGER DEFAULT 0,
        comment_count INTEGER DEFAULT 0,
        created_at    TEXT DEFAULT (datetime('now', 'localtime'))
    );
    CREATE INDEX IF NOT EXISTS idx_time   ON items(create_time DESC);
    CREATE INDEX IF NOT EXISTS idx_tags   ON items(tags);
    CREATE INDEX IF NOT EXISTS idx_stocks ON items(stocks);
    """

    def __init__(self, db_path: str = "sina_7x24.db"):
        self.db_path = db_path
        self._init_db()

    @contextmanager
    def _conn(self):
        conn = sqlite3.connect(self.db_path)
        conn.row_factory = sqlite3.Row
        try:
            yield conn
            conn.commit()
        except Exception:
            conn.rollback()
            raise
        finally:
            conn.close()

    def _init_db(self):
        with self._conn() as conn:
            for stmt in self.CREATE_SQL.strip().split(";"):
                if stmt.strip():
                    conn.execute(stmt)

    def upsert(self, items: List[FeedItem]) -> int:
        """插入或更新快讯条目（按ID去重）"""
        sql = """
        INSERT OR REPLACE INTO items
            (id, create_time, update_time, rich_text, tags, stocks,
             images, doc_url, like_nums, comment_count)
        VALUES (?,?,?,?,?,?,?,?,?,?)
        """
        rows = [
            (
                item.id, item.create_time, item.update_time,
                item.rich_text,
                json.dumps(item.tag_names, ensure_ascii=False),
                json.dumps(item.stock_names, ensure_ascii=False),
                json.dumps(item.images, ensure_ascii=False),
                item.doc_url, item.like_nums, item.comment_count,
            )
            for item in items
        ]
        with self._conn() as conn:
            conn.executemany(sql, rows)
        return len(rows)

    def query(
        self,
        keyword: Optional[str] = None,
        tag: Optional[str] = None,
        stock: Optional[str] = None,
        start_date: Optional[str] = None,
        end_date: Optional[str] = None,
        limit: int = 50,
    ) -> List[sqlite3.Row]:
        """灵活查询快讯"""
        conditions, params = [], []

        if keyword:
            conditions.append("rich_text LIKE ?")
            params.append(f"%{keyword}%")
        if tag:
            conditions.append("tags LIKE ?")
            params.append(f"%{tag}%")
        if stock:
            conditions.append("stocks LIKE ?")
            params.append(f"%{stock}%")
        if start_date:
            conditions.append("create_time >= ?")
            params.append(start_date)
        if end_date:
            conditions.append("create_time <= ?")
            params.append(end_date)

        where = f"WHERE {' AND '.join(conditions)}" if conditions else ""
        sql = f"SELECT * FROM items {where} ORDER BY create_time DESC LIMIT ?"
        params.append(limit)

        with self._conn() as conn:
            return conn.execute(sql, params).fetchall()

    def get_stats(self) -> dict:
        """获取数据库统计信息"""
        with self._conn() as conn:
            total = conn.execute("SELECT COUNT(*) FROM items").fetchone()[0]
            oldest = conn.execute("SELECT MIN(create_time) FROM items").fetchone()[0]
            newest = conn.execute("SELECT MAX(create_time) FROM items").fetchone()[0]
        return {"total": total, "oldest": oldest, "newest": newest}


# ─── 示例 ──────────────────────────────────────────────────────────────────────
if __name__ == "__main__":
    from sina_7x24_client import Sina7x24Client, TagID

    client = Sina7x24Client()
    db = FeedDatabase("news.db")

    # 批量导入历史数据
    for resp in client.iter_history(TagID.ALL, max_pages=5):
        count = db.upsert(resp.items)
        print(f"已存储 {count} 条 (page {resp.page_info.page})")

    stats = db.get_stats()
    print(f"\\n数据库统计: {stats}")

    # 搜索示例
    rows = db.query(keyword="美联储", limit=10)
    print(f"\\n搜索'美联储'找到 {len(rows)} 条")
    for row in rows[:3]:
        print(f"  [{row['create_time']}] {row['rich_text'][:60]}...")
`;

const minimalCode = `#!/usr/bin/env python3
# -*- coding: utf-8 -*-
"""
极简版 - 30行实现基础功能
适合快速集成到现有项目
"""

import json, re, time, requests

_SESSION = requests.Session()
_SESSION.headers["Referer"] = "https://finance.sina.com.cn/"
_LAST = 0

def fetch(tag_id=0, page=1, cursor_id=0, dire="f"):
    """
    获取新浪财经7×24快讯

    Returns:
        list of dict: [{id, time, text, stocks, tags, url}, ...]
    """
    global _LAST
    elapsed = time.time() - _LAST
    if elapsed < 1.0: time.sleep(1.0 - elapsed)

    r = _SESSION.get("https://zhibo.sina.com.cn/api/zhibo/feed", params={
        "callback":"cb", "zhibo_id":152, "dpc":1, "type":0,
        "page":page, "page_size":20, "tag_id":tag_id,
        "dire":dire, "id":cursor_id, "_":int(time.time()*1000)
    }, timeout=10)
    _LAST = time.time()

    m = re.search(r'\\(({.*})\\)', r.text, re.DOTALL)
    if not m: return []
    feed = json.loads(m.group(1))["result"]["data"]["feed"]

    results = []
    for item in feed.get("list", []):
        if item.get("is_delete"): continue
        ext = {}
        try: ext = json.loads(item.get("ext","{}"))
        except: pass
        results.append({
            "id":     item["id"],
            "time":   item["create_time"],
            "text":   item["rich_text"],
            "stocks": [s["key"] for s in ext.get("stocks",[])],
            "tags":   [t["name"] for t in item.get("tag",[])],
            "url":    ext.get("docurl",""),
        })
    return results, {"max_id": feed.get("max_id",0), "min_id": feed.get("min_id",0)}


# 使用示例
if __name__ == "__main__":
    items, meta = fetch()
    for item in items[:3]:
        print(f"[{item['time']}] {item['text'][:60]}")
        if item['stocks']: print(f"  股票: {item['stocks']}")
    print(f"\\nmax_id={meta['max_id']}, min_id={meta['min_id']}")
`;

const skillDoc = `# 新浪财经7×24快讯 API Skill

## 触发场景
- 用户询问新浪财经快讯/7x24/实时新闻
- 需要抓取A股/港股/美股实时资讯
- 构建股票新闻监控系统
- 爬取财经快讯数据集

## API快速参考

| 端点 | https://zhibo.sina.com.cn/api/zhibo/feed |
|------|------------------------------------------|
| 格式 | JSONP GET |
| 固定 | zhibo_id=152, dpc=1, type=0 |

### 最简请求
\`\`\`
GET /api/zhibo/feed?callback=cb&zhibo_id=152&dpc=1&type=0
    &page=1&page_size=20&tag_id=0&dire=f&id=0
    &_=<timestamp_ms>
\`\`\`

### tag_id 对照
0全部 | 1宏观 | 2行业 | 3公司 | 5市场 | 8其他
9焦点 | 10 A股 | 102国际 | 110两会 | 202原创

## 3步解析流程

### Step 1: 剥离JSONP
\`\`\`python
import re, json
m = re.search(r'\\(({.*})\\)', resp.text, re.DOTALL)
data = json.loads(m.group(1))  # 主JSON对象
\`\`\`

### Step 2: 提取数据
\`\`\`python
feed = data["result"]["data"]["feed"]
items_raw = feed["list"]
max_id = feed["max_id"]  # 用于增量更新
min_id = feed["min_id"]  # 用于翻历史页
\`\`\`

### Step 3: 解析条目
\`\`\`python
for item in items_raw:
    if item["is_delete"]: continue  # 必须过滤！
    text  = item["rich_text"]       # Unicode自动解码
    time_ = item["create_time"]
    ext   = json.loads(item["ext"]) # 二次解析！
    stocks = ext.get("stocks", [])  # [{market,symbol,key}]
    url   = ext.get("docurl", "")
\`\`\`

## 分页策略
- **初始/最新**: id=0, dire=f, page=1
- **翻历史**: id=min_id, dire=b, page+1
- **增量更新**: id=max_id, dire=f

## 常见错误

| 错误 | 原因 | 解决 |
|------|------|------|
| JSON解析失败 | JSONP未剥离 | re.search提取括号内容 |
| 出现已删除内容 | 未过滤 | 检查is_delete==0 |
| ext.stocks为空 | 未二次解析 | json.loads(item["ext"]) |
| 请求被限流 | 频率过高 | 间隔≥1秒 |
| 无数据返回 | tag_id不存在 | 检查tag_id取值范围 |

## 生产建议
- 随机延迟: random.uniform(0.8, 2.0) 秒
- 异常重试: 指数退避，最多3次
- 数据去重: 以id为主键 INSERT OR REPLACE
- 监控间隔: 30-60秒轮询增量

## 文件结构
\`\`\`
sina_7x24_client.py   # 主客户端（完整功能）
monitor.py            # 实时监控器
async_client.py       # 异步并发版
feed_database.py      # SQLite存储
minimal_fetch.py      # 极简30行版
\`\`\`
