import json, sqlite3
from contextlib import contextmanager
from typing import List, Optional
from sina_7x24_client import FeedItem

class FeedDatabase:
    SCHEMA = """
    CREATE TABLE IF NOT EXISTS items (
        id            INTEGER PRIMARY KEY,
        create_time   TEXT    NOT NULL,
        update_time   TEXT,
        rich_text     TEXT    NOT NULL,
        tags          TEXT,
        stocks        TEXT,
        images        TEXT,
        doc_url       TEXT,
        like_nums     INTEGER DEFAULT 0,
        comment_count INTEGER DEFAULT 0
    );
    CREATE INDEX IF NOT EXISTS idx_time   ON items(create_time DESC);
    CREATE INDEX IF NOT EXISTS idx_stocks ON items(stocks);
    """

    def __init__(self, path="sina_7x24.db"):
        self.path = path
        with self._conn() as c:
            for s in self.SCHEMA.strip().split(";"):
                if s.strip(): c.execute(s)

    @contextmanager
    def _conn(self):
        conn = sqlite3.connect(self.path)
        conn.row_factory = sqlite3.Row
        try: yield conn; conn.commit()
        except: conn.rollback(); raise
        finally: conn.close()

    def upsert(self, items: List[FeedItem]) -> int:
        sql = """INSERT OR REPLACE INTO items
            (id,create_time,update_time,rich_text,tags,stocks,images,doc_url,like_nums,comment_count)
            VALUES (?,?,?,?,?,?,?,?,?,?)"""
        rows = [(i.id,i.create_time,i.update_time,i.rich_text,
                 json.dumps(i.tag_names,ensure_ascii=False),
                 json.dumps(i.stock_names,ensure_ascii=False),
                 json.dumps(i.images,ensure_ascii=False),
                 i.doc_url,i.like_nums,i.comment_count) for i in items]
        with self._conn() as c: c.executemany(sql, rows)
        return len(rows)

    def query(self, keyword=None, tag=None, stock=None,
              start_date=None, end_date=None, limit=50):
        conds, params = [], []
        if keyword: conds.append("rich_text LIKE ?"); params.append(f"%{keyword}%")
        if tag:     conds.append("tags LIKE ?");      params.append(f"%{tag}%")
        if stock:   conds.append("stocks LIKE ?");    params.append(f"%{stock}%")
        if start_date: conds.append("create_time >= ?"); params.append(start_date)
        if end_date:   conds.append("create_time <= ?"); params.append(end_date)
        where = f"WHERE {' AND '.join(conds)}" if conds else ""
        with self._conn() as c:
            return c.execute(f"SELECT * FROM items {where} ORDER BY create_time DESC LIMIT ?",
                             params+[limit]).fetchall()

    def stats(self):
        with self._conn() as c:
            row = c.execute("SELECT COUNT(*),MIN(create_time),MAX(create_time) FROM items").fetchone()
            return {"total":row[0],"oldest":row[1],"newest":row[2]}

