const CODES = {
client: `#!/usr/bin/env python3
# -*- coding: utf-8 -*-
"""
sina_7x24_client.py
新浪财经 7×24 快讯 API 完整客户端

依赖: pip install requests
"""

import csv
import json
import random
import re
import time
from dataclasses import dataclass, field
from enum import IntEnum
from typing import Dict, Generator, List, Optional

import requests


# ─── 枚举：分类标签 ──────────────────────────────────────────────────────
class TagID(IntEnum):
    ALL      = 0    # 全部
    MACRO    = 1    # 宏观
    INDUSTRY = 2    # 行业
    COMPANY  = 3    # 公司
    MARKET   = 5    # 市场
    OTHER    = 8    # 其他
    FOCUS    = 9    # 焦点
    A_SHARE  = 10   # A 股
    INTL     = 102  # 国际
    TWO_SESS = 110  # 两会（时效性标签）
    ORIGINAL = 202  # 原创


# ─── 数据模型 ────────────────────────────────────────────────────────────
@dataclass
class StockRef:
    market: str   # cn / us / hk / fund / global / ...
    symbol: str
    name:   str

    def __str__(self) -> str:
        return f"{self.name}({self.market}:{self.symbol})"


@dataclass
class FeedItem:
    id:            int
    type:          int          # 0=文本  1=含图片
    rich_text:     str
    create_time:   str
    update_time:   str
    is_delete:     int
    tags:          List[Dict]   = field(default_factory=list)
    stocks:        List[StockRef] = field(default_factory=list)
    images:        List[str]    = field(default_factory=list)
    doc_url:       str          = ""
    like_nums:     int          = 0
    comment_count: int          = 0

    @property
    def tag_names(self) -> List[str]:
        return [t.get("name", "") for t in self.tags]

    @property
    def stock_names(self) -> List[str]:
        return [s.name for s in self.stocks]

    def __str__(self) -> str:
        return f"[{self.create_time}] {self.rich_text[:80]}..."


@dataclass
class PageInfo:
    total_page: int
    page_size:  int
    page:       int
    total_num:  int


@dataclass
class FeedResponse:
    items:     List[FeedItem]
    max_id:    int
    min_id:    int
    page_info: PageInfo
    raw:       Dict = field(default_factory=dict, repr=False)

    @property
    def has_more(self) -> bool:
        return self.page_info.page < self.page_info.total_page


# ─── 解析工具 ────────────────────────────────────────────────────────────
def _strip_jsonp(text: str) -> Dict:
    """剥离 JSONP 包装，提取内部 JSON 对象"""
    m = re.search(r"\((\{.*\})\)", text, re.DOTALL)
    if not m:
        raise ValueError(f"无法解析 JSONP 响应: {text[:200]}")
    return json.loads(m.group(1))


def _parse_stocks(ext_str: str) -> List[StockRef]:
    """从 ext JSON 字符串中提取股票引用（二次解析）"""
    if not ext_str:
        return []
    try:
        ext = json.loads(ext_str)
        return [
            StockRef(
                market=s.get("market", ""),
                symbol=s.get("symbol", ""),
                name=s.get("key", ""),
            )
            for s in (ext.get("stocks") or [])
            if isinstance(s, dict)
        ]
    except (json.JSONDecodeError, TypeError):
        return []


def _parse_docurl(ext_str: str) -> str:
    try:
        return json.loads(ext_str).get("docurl", "")
    except (json.JSONDecodeError, TypeError):
        return ""


def _parse_item(raw: Dict) -> FeedItem:
    ext_str   = raw.get("ext", "")
    multimedia = raw.get("multimedia") or {}
    img_urls  = multimedia.get("img_url") or []
    comments  = raw.get("comment_list") or {}
    return FeedItem(
        id            = int(raw.get("id", 0)),
        type          = int(raw.get("type", 0)),
        rich_text     = raw.get("rich_text", ""),
        create_time   = raw.get("create_time", ""),
        update_time   = raw.get("update_time", ""),
        is_delete     = int(raw.get("is_delete", 0)),
        tags          = raw.get("tag") or [],
        stocks        = _parse_stocks(ext_str),
        images        = img_urls if isinstance(img_urls, list) else [],
        doc_url       = _parse_docurl(ext_str),
        like_nums     = int(raw.get("like_nums", 0)),
        comment_count = int(comments.get("total", 0)),
    )


def _parse_response(data: Dict) -> FeedResponse:
    status = data.get("result", {}).get("status", {})
    if status.get("code") != 0:
        raise ValueError(f"API 错误: {status.get('msg')} (code={status.get('code')})")

    feed     = data["result"]["data"]["feed"]
    raw_list = feed.get("list") or []
    items    = [_parse_item(r) for r in raw_list if r.get("is_delete") == 0]

    pi = feed.get("page_info") or {}
    return FeedResponse(
        items=items,
        max_id=int(feed.get("max_id", 0)),
        min_id=int(feed.get("min_id", 0)),
        page_info=PageInfo(
            total_page=int(pi.get("totalPage", 1)),
            page_size=int(pi.get("pageSize", 20)),
            page=int(pi.get("page", 1)),
            total_num=int(pi.get("totalNum", 0)),
        ),
        raw=data,
    )


# ─── 主客户端 ────────────────────────────────────────────────────────────
class Sina7x24Client:
    """
    新浪财经 7×24 快讯客户端

    Example:
        client = Sina7x24Client()
        resp = client.get_latest()
        for item in resp.items:
            print(item)
    """

    BASE_URL = "https://zhibo.sina.com.cn/api/zhibo/feed"
    ZHIBO_ID = 152

    def __init__(self, delay: float = 1.0) -> None:
        self.delay     = delay
        self._last_req = 0.0
        self.session   = requests.Session()
        self.session.headers.update({
            "User-Agent": (
                "Mozilla/5.0 (Windows NT 10.0; Win64; x64) "
                "AppleWebKit/537.36 (KHTML, like Gecko) "
                "Chrome/120.0.0.0 Safari/537.36"
            ),
            "Referer": "https://finance.sina.com.cn/",
            "Accept":  "*/*",
        })

    # ── 内部工具 ───────────────────────────────────────────────────────
    def _throttle(self) -> None:
        elapsed = time.time() - self._last_req
        if elapsed < self.delay:
            time.sleep(self.delay - elapsed + random.uniform(0, 0.3))
        self._last_req = time.time()

    def _request(self, params: Dict) -> FeedResponse:
        self._throttle()
        base = {
            "callback": "feedCallback",
            "zhibo_id": self.ZHIBO_ID,
            "dpc":      1,
            "type":     0,
            "_":        int(time.time() * 1000),
        }
        base.update(params)
        resp = self.session.get(self.BASE_URL, params=base, timeout=10)
        resp.raise_for_status()
        return _parse_response(_strip_jsonp(resp.text))

    # ── 公开 API ───────────────────────────────────────────────────────
    def get_latest(self, tag_id: TagID = TagID.ALL) -> FeedResponse:
        """获取最新快讯（第 1 页）"""
        return self._request(
            {"page": 1, "page_size": 20, "tag_id": int(tag_id), "dire": "f", "id": 0}
        )

    def get_page(self, tag_id: TagID = TagID.ALL, page: int = 1) -> FeedResponse:
        """获取指定页码"""
        return self._request(
            {"page": page, "page_size": 20, "tag_id": int(tag_id), "dire": "f", "id": 0}
        )

    def get_next_page(self, prev: FeedResponse, tag_id: TagID = TagID.ALL) -> FeedResponse:
        """基于前一响应获取下一历史页"""
        return self._request({
            "page":      prev.page_info.page + 1,
            "page_size": 20,
            "tag_id":    int(tag_id),
            "dire":      "b",
            "id":        prev.min_id,
        })

    def get_updates(self, since_id: int, tag_id: TagID = TagID.ALL) -> FeedResponse:
        """增量更新：获取比 since_id 更新的内容"""
        return self._request(
            {"page": 1, "page_size": 20, "tag_id": int(tag_id), "dire": "f", "id": since_id}
        )

    def iter_history(
        self, tag_id: TagID = TagID.ALL, max_pages: int = 10
    ) -> Generator[FeedResponse, None, None]:
        """自动翻页迭代历史数据"""
        resp = self.get_latest(tag_id)
        yield resp
        for _ in range(max_pages - 1):
            if not resp.has_more:
                break
            resp = self.get_next_page(resp, tag_id)
            yield resp

    def search(
        self, keyword: str, tag_id: TagID = TagID.ALL, max_pages: int = 5
    ) -> List[FeedItem]:
        """在历史快讯中搜索关键词"""
        return [
            item
            for resp in self.iter_history(tag_id, max_pages)
            for item in resp.items
            if keyword in item.rich_text
        ]

    def get_stock_news(self, name: str, max_pages: int = 5) -> List[FeedItem]:
        """获取包含指定股票的快讯"""
        return [
            item
            for resp in self.iter_history(TagID.ALL, max_pages)
            for item in resp.items
            if any(name in s.name or name in s.symbol for s in item.stocks)
