"""
monitor.py
新浪财经 7×24 实时快讯监控器

持续轮询增量更新，新内容通过回调通知。
"""

import time
from typing import Callable, Set

from sina_7x24_client import FeedItem, Sina7x24Client, TagID


class FeedMonitor:
    """
    实时监控器

    Example:
        monitor = FeedMonitor(tag_id=TagID.ALL)

        @monitor.on_new_item
        def handle(item: FeedItem):
            print(f"新快讯: {item}")

        monitor.start(interval=30)
    """

    def __init__(self, tag_id: TagID = TagID.ALL, delay: float = 1.0) -> None:
        self.client     = Sina7x24Client(delay=delay)
        self.tag_id     = tag_id
        self._seen_ids: Set[int] = set()
        self._callbacks: list   = []
        self._max_id    = 0

    def on_new_item(self, fn: Callable[[FeedItem], None]):
        """装饰器：注册新快讯回调"""
        self._callbacks.append(fn)
        return fn

    # ── 内部方法 ───────────────────────────────────────────────────────
    def _initialize(self) -> None:
        """启动时记录已有条目 ID，避免触发历史通知"""
        print("⟳  初始化，加载现有条目 ID...")
        resp = self.client.get_latest(self.tag_id)
        self._seen_ids = {item.id for item in resp.items}
        self._max_id   = resp.max_id
        print(f"✓  已记录 {len(self._seen_ids)} 条，max_id = {self._max_id}")

    def _check(self) -> int:
        resp     = self.client.get_updates(self._max_id, self.tag_id)
        new_items = [i for i in resp.items if i.id not in self._seen_ids]

        for item in sorted(new_items, key=lambda x: x.id):
            self._seen_ids.add(item.id)
            for cb in self._callbacks:
                try:
                    cb(item)
                except Exception as e:
                    print(f"⚠  回调异常: {e}")

        if resp.max_id > self._max_id:
            self._max_id = resp.max_id
        return len(new_items)

    # ── 公开 API ───────────────────────────────────────────────────────
    def start(self, interval: int = 30) -> None:
        """开始监控（阻塞，Ctrl-C 停止）"""
        self._initialize()
        print(f"◉  监控已启动，轮询间隔 {interval} 秒\n")
        while True:
            try:
                n = self._check()
                if n:
                    print(f"  📬 {n} 条新快讯")
                time.sleep(interval)
            except KeyboardInterrupt:
                print("\n⏹  监控已停止")
                break
            except Exception as e:
                print(f"  ✗ 请求异常: {e}，{interval} 秒后重试...")
                time.sleep(interval)


# ─── 示例 ────────────────────────────────────────────────────────────────
if __name__ == "__main__":
    monitor = FeedMonitor(tag_id=TagID.ALL)

