依赖: pip install aiohttp
"""

import asyncio
import time
from typing import AsyncGenerator, Dict

import aiohttp

from sina_7x24_client import (
    FeedResponse,
    TagID,
    _parse_response,
    _strip_jsonp,
)


class AsyncSina7x24Client:
    """
    异步客户端，适合并发获取多分类数据

    Example:
        async with AsyncSina7x24Client() as client:
            resp = await client.get_latest()
            all_cats = await client.fetch_all_categories()
    """

    BASE_URL = "https://zhibo.sina.com.cn/api/zhibo/feed"
    ZHIBO_ID = 152

    def __init__(self, delay: float = 0.5) -> None:
        self.delay    = delay
        self._session: aiohttp.ClientSession | None = None

    async def __aenter__(self):
        self._session = aiohttp.ClientSession(headers={
            "User-Agent": (
                "Mozilla/5.0 (Windows NT 10.0; Win64; x64) "
                "AppleWebKit/537.36 (KHTML, like Gecko) "
                "Chrome/120.0.0.0 Safari/537.36"
            ),
            "Referer": "https://finance.sina.com.cn/",
        })
        return self

    async def __aexit__(self, *_):
        await self._session.close()

    # ── 内部工具 ───────────────────────────────────────────────────────
    async def _request(self, params: Dict) -> FeedResponse:
        base = {
            "callback": "feedCallback",
            "zhibo_id": self.ZHIBO_ID,
            "dpc":      1,
            "type":     0,
            "_":        int(time.time() * 1000),
        }
        base.update(params)
        async with self._session.get(
            self.BASE_URL, params=base,
            timeout=aiohttp.ClientTimeout(total=10),
        ) as resp:
            resp.raise_for_status()
            text = await resp.text()
        return _parse_response(_strip_jsonp(text))

    # ── 公开 API ───────────────────────────────────────────────────────
    async def get_latest(self, tag_id: TagID = TagID.ALL) -> FeedResponse:
        return await self._request(
            {"page": 1, "page_size": 20, "tag_id": int(tag_id), "dire": "f", "id": 0}
        )

    async def get_updates(self, since_id: int, tag_id: TagID = TagID.ALL) -> FeedResponse:
        return await self._request(
            {"page": 1, "page_size": 20, "tag_id": int(tag_id), "dire": "f", "id": since_id}
        )

    async def fetch_all_categories(self) -> Dict[TagID, FeedResponse]:
        """并发获取所有分类最新快讯（自动错开请求，避免瞬时并发）"""
        tags = list(TagID)

        async def one(tag: TagID):
            await asyncio.sleep(self.delay * tags.index(tag) * 0.4)
            return tag, await self.get_latest(tag)

        results = await asyncio.gather(*[one(t) for t in tags], return_exceptions=True)
        return {
            tag: resp
            for tag, resp in results
            if not isinstance(resp, Exception)
        }

    async def iter_pages(
        self, tag_id: TagID = TagID.ALL, max_pages: int = 5
    ) -> AsyncGenerator[FeedResponse, None]:
        """异步迭代多页历史"""
        resp = await self.get_latest(tag_id)
        yield resp
        for _ in range(max_pages - 1):
            if not resp.has_more:
                break
            await asyncio.sleep(self.delay)
            resp = await self._request({
                "page":      resp.page_info.page + 1,
                "page_size": 20,
                "tag_id":    int(tag_id),
                "dire":      "b",
                "id":        resp.min_id,
            })
            yield resp


# ─── 示例 ────────────────────────────────────────────────────────────────
async def main() -> None:
    async with AsyncSina7x24Client(delay=0.5) as client:
        print("⟳  并发获取所有分类...\n")
        cats = await client.fetch_all_categories()
        for tag, resp in cats.items():
