"""
feed_database.py
新浪财经 7×24 快讯 SQLite 持久化存储
"""

import json
import sqlite3
from contextlib import contextmanager
from typing import List, Optional

from sina_7x24_client import FeedItem, Sina7x24Client, TagID


class FeedDatabase:
    """
    SQLite 持久化存储，以 id 为主键去重

    Example:
        db = FeedDatabase("news.db")
        db.upsert(items)
        rows = db.query(keyword="美联储", limit=20)
    """

    _SCHEMA = """
    CREATE TABLE IF NOT EXISTS items (
        id            INTEGER PRIMARY KEY,
        create_time   TEXT    NOT NULL,
        update_time   TEXT,
        rich_text     TEXT    NOT NULL,
        tags          TEXT,
        stocks        TEXT,
        images        TEXT,
        doc_url       TEXT,
        like_nums     INTEGER DEFAULT 0,
        comment_count INTEGER DEFAULT 0,
        saved_at      TEXT    DEFAULT (datetime('now','localtime'))
    );
    CREATE INDEX IF NOT EXISTS idx_time   ON items(create_time DESC);
    CREATE INDEX IF NOT EXISTS idx_stocks ON items(stocks);
    CREATE INDEX IF NOT EXISTS idx_tags   ON items(tags);
    """

    def __init__(self, db_path: str = "sina_7x24.db") -> None:
        self.db_path = db_path
        with self._conn() as c:
            for stmt in self._SCHEMA.strip().split(";"):
                if stmt.strip():
                    c.execute(stmt)

    @contextmanager
    def _conn(self):
        conn = sqlite3.connect(self.db_path)
        conn.row_factory = sqlite3.Row
        try:
            yield conn
            conn.commit()
        except Exception:
            conn.rollback()
            raise
        finally:
            conn.close()

    def upsert(self, items: List[FeedItem]) -> int:
        """插入或替换条目（以 id 去重）"""
        sql = """INSERT OR REPLACE INTO items
            (id, create_time, update_time, rich_text,
             tags, stocks, images, doc_url, like_nums, comment_count)
            VALUES (?,?,?,?,?,?,?,?,?,?)"""
        rows = [
            (
                item.id, item.create_time, item.update_time, item.rich_text,
                json.dumps(item.tag_names,   ensure_ascii=False),
                json.dumps(item.stock_names, ensure_ascii=False),
                json.dumps(item.images,      ensure_ascii=False),
                item.doc_url, item.like_nums, item.comment_count,
            )
            for item in items
        ]
        with self._conn() as c:
            c.executemany(sql, rows)
        return len(rows)

    def query(
        self,
        keyword:    Optional[str] = None,
        tag:        Optional[str] = None,
        stock:      Optional[str] = None,
        start_date: Optional[str] = None,
        end_date:   Optional[str] = None,
        limit:      int           = 50,
    ) -> list:
        conds, params = [], []
        if keyword:    conds.append("rich_text LIKE ?");    params.append(f"%{keyword}%")
        if tag:        conds.append("tags LIKE ?");         params.append(f"%{tag}%")
        if stock:      conds.append("stocks LIKE ?");       params.append(f"%{stock}%")
        if start_date: conds.append("create_time >= ?");    params.append(start_date)
        if end_date:   conds.append("create_time <= ?");    params.append(end_date)
        where = f"WHERE {' AND '.join(conds)}" if conds else ""
        sql   = f"SELECT * FROM items {where} ORDER BY create_time DESC LIMIT ?"
        with self._conn() as c:
            return c.execute(sql, params + [limit]).fetchall()

    def stats(self) -> dict:
        with self._conn() as c:
            r = c.execute(
                "SELECT COUNT(*), MIN(create_time), MAX(create_time) FROM items"
            ).fetchone()
            return {"total": r[0], "oldest": r[1], "newest": r[2]}


# ─── 示例 ────────────────────────────────────────────────────────────────
if __name__ == "__main__":
    client = Sina7x24Client()
    db     = FeedDatabase("news.db")

    print("▸ 批量导入历史数据...")
    for resp in client.iter_history(TagID.ALL, max_pages=5):
        n = db.upsert(resp.items)
        print(f"  page {resp.page_info.page}: 存储 {n} 条")

    print("\n▸ 数据库统计:", db.stats())

    print("\n▸ 搜索「美联储」:")
    for row in db.query(keyword="美联储", limit=5):
        print(f"  [{row['create_time']}] {row['rich_text'][:60]}...")`,

