"""
minimal_fetch.py
30 行极简版 — 零外部依赖（仅 requests）
适合快速集成到现有项目
"""

import json
import re
import time

import requests

_SESSION = requests.Session()
_SESSION.headers["Referer"] = "https://finance.sina.com.cn/"
_LAST_REQ = 0.0


def fetch(tag_id: int = 0, page: int = 1, cursor_id: int = 0, dire: str = "f"):
    """
    获取新浪财经 7×24 快讯

    Returns:
        (items, meta)
        items: list[dict]  — 每项含 id / time / text / stocks / tags / url
        meta:  dict        — 含 max_id / min_id，用于翻页和增量更新
    """
    global _LAST_REQ
    gap = time.time() - _LAST_REQ
    if gap < 1.0:
        time.sleep(1.0 - gap)

    r = _SESSION.get(
        "https://zhibo.sina.com.cn/api/zhibo/feed",
        params={
            "callback": "cb", "zhibo_id": 152, "dpc": 1, "type": 0,
            "page": page, "page_size": 20, "tag_id": tag_id,
            "dire": dire, "id": cursor_id, "_": int(time.time() * 1000),
        },
        timeout=10,
    )
    _LAST_REQ = time.time()

    m = re.search(r"\((\{.*\})\)", r.text, re.DOTALL)
    if not m:
        return [], {}

    feed = json.loads(m.group(1))["result"]["data"]["feed"]
    items = []
    for x in feed.get("list", []):
        if x.get("is_delete"):           # 跳过已删除
            continue
        ext = {}
        try:
            ext = json.loads(x.get("ext", "{}"))   # 二次解析
        except (json.JSONDecodeError, TypeError):
            pass
        items.append({
            "id":     x["id"],
            "time":   x["create_time"],
            "text":   x["rich_text"],
            "stocks": [s["key"] for s in ext.get("stocks", [])],
            "tags":   [t["name"] for t in x.get("tag", [])],
            "url":    ext.get("docurl", ""),
        })

    meta = {"max_id": feed.get("max_id", 0), "min_id": feed.get("min_id", 0)}
    return items, meta


# ─── 示例 ────────────────────────────────────────────────────────────────
if __name__ == "__main__":
    items, meta = fetch()                       # tag_id=0 全部，最新一页
    for item in items[:3]:
        print(f"[{item['time']}] {item['text'][:60]}")
        if item["stocks"]:
            print(f"  📈 {item['stocks']}")
    print(f"\nmax_id={meta['max_id']}  # 增量更新游标")
    print(f"min_id={meta['min_id']}  # 历史翻页游标")`,

