export default function App() {
  const [tab, setTab] = useState("api");
  const [copied, setCopied] = useState(null);
  const contentRef = useRef(null);

  useEffect(() => {
    if (contentRef.current) contentRef.current.scrollTop = 0;
  }, [tab]);

  const filenames = {
    client: "sina_7x24_client.py",
