    client: "client", monitor: "monitor", async: "async_c",
    db: "db", minimal: "minimal", skill: "skill",
  };

  const copyCode = (key) => {
    const codeKey = tabToCode[key] || key;
    navigator.clipboard.writeText(CODES[codeKey]).then(() => {
      setCopied(key); setTimeout(() => setCopied(null), 2000);
    });
