          </div>
          <button onClick={() => copyCode(tabId)} style={{
            background: copied === tabId ? PALETTE.green + "22" : PALETTE.surface,
            color: copied === tabId ? PALETTE.green : PALETTE.muted,
            border: `1px solid ${copied === tabId ? PALETTE.green + "55" : PALETTE.border}`,
            borderRadius: 6, padding: "6px 18px", fontSize: 12,
            cursor: "pointer", fontFamily: "monospace", transition: "all 0.2s",
            letterSpacing: "0.04em",
          }}>{copied === tabId ? "✓  已复制" : "⊕  复制全部"}</button>
        </div>
        <CodeBlock code={CODES[codeKey]} filename={fname} />
      </div>
    );
  };

  return (
    <div style={{
      background: PALETTE.bg, minHeight: "100vh", color: PALETTE.text,
      fontFamily: "'Segoe UI', 'PingFang SC', 'Microsoft YaHei', sans-serif",
      display: "flex", flexDirection: "column",
    }}>
      {/* Header */}
      <div style={{
        background: PALETTE.surface,
        borderBottom: `1px solid ${PALETTE.border}`,
        padding: "1.4rem 2rem",
        flexShrink: 0,
      }}>
        <div style={{ display: "flex", alignItems: "flex-start", justifyContent: "space-between", flexWrap: "wrap", gap: 12 }}>
          <div>
            <div style={{ display: "flex", alignItems: "center", gap: 10, marginBottom: 6 }}>
              <div style={{
                width: 8, height: 8, borderRadius: "50%",
                background: PALETTE.green, boxShadow: `0 0 8px ${PALETTE.green}`,
                animation: "pulse 2s ease-in-out infinite",
              }} />
              <h1 style={{ margin: 0, fontSize: "1.3rem", fontWeight: 700, color: "#fff", letterSpacing: "-0.01em" }}>
                新浪财经 7×24 快讯 API
              </h1>
            </div>
            <p style={{ margin: 0, color: PALETTE.muted, fontSize: 13 }}>
              完整文档包 · API 分析 + Python 客户端 + 实时监控 + 异步版 + SQLite + Skill 文档
            </p>
          </div>
          <div style={{ display: "flex", gap: 6, flexWrap: "wrap", alignItems: "flex-start" }}>
            {[
              ["JSONP GET", PALETTE.accent],
              ["zhibo_id=152", PALETTE.green],
              ["requests / aiohttp", PALETTE.yellow],
              ["SQLite", PALETTE.purple],
              ["实时监控", PALETTE.red],
            ].map(([l, c]) => <Badge key={l} color={c}>{l}</Badge>)}
          </div>
        </div>
      </div>

      {/* Tab Bar */}
      <div style={{
        background: PALETTE.surface, borderBottom: `1px solid ${PALETTE.border}`,
        padding: "0 1.5rem", display: "flex", overflowX: "auto", flexShrink: 0,
      }}>
        {TABS.map(t => (
