      </div>

      {/* Content */}
      <div ref={contentRef} style={{
        flex: 1, overflowY: "auto", padding: "2rem",
        maxWidth: 1100, margin: "0 auto", width: "100%", boxSizing: "border-box",
      }}>
        {tab === "api"     && <ApiTab />}
        {tab === "client"  && renderCodeTab("client")}
        {tab === "monitor" && renderCodeTab("monitor")}
        {tab === "async"   && renderCodeTab("async")}
